// The smallest database interface the backend logic needs. The Edge Functions implement it with supabase-js,
// the tests implement it on a real in-memory Postgres. Keeping it this small means the same logic is tested and deployed.

export type Scalar = string | number | boolean | null;

export interface SelectOptions {
  columns?: string;
  eq?: Record<string, Scalar>;
  in?: Record<string, (string | number)[]>;
  gte?: Record<string, string | number>;
  lte?: Record<string, string | number>;
  order?: { column: string; ascending?: boolean };
  limit?: number;
}

export interface Db {
  select<T = Record<string, unknown>>(table: string, options?: SelectOptions): Promise<T[]>;
  /** inserts rows and returns the requested columns of the new rows */
  insert<T = Record<string, unknown>>(table: string, rows: Record<string, unknown>[], returning?: string): Promise<T[]>;
  upsert(table: string, row: Record<string, unknown>, onConflict: string): Promise<void>;
  /** upserts many rows (the hourly weather of a field: about 100 rows) */
  upsertMany(table: string, rows: Record<string, unknown>[], onConflict: string): Promise<void>;
  update(table: string, values: Record<string, unknown>, where: Record<string, Scalar>): Promise<void>;
}

/** numeric columns arrive as numbers from PostgREST and as strings from some drivers; null stays null */
export function toNum(x: unknown): number | null {
  if (x === null || x === undefined || x === '') return null;
  const n = typeof x === 'number' ? x : Number(x);
  return Number.isFinite(n) ? n : null;
}
